toolArgs.file_text:
@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>
<h3 class="mb-3">Kanban Board</h3>

@if (loading)
{
    <div class="text-center py-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
        <p class="mt-2">Loading tasks...</p>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">@errorMessage</div>
}
else
{
    <BoardStats Total="allTasks.Count"
                ToDo="TodoTasks.Count"
                InProgress="InProgressTasks.Count"
                DoneCount="DoneTasks.Count"
                Overdue="OverdueCount" />

    <BoardSearchBar SearchText="@searchText" OnSearchChanged="HandleSearch" />

    <div class="row g-3">
        <BoardColumn ColumnName="To Do"
                     Tasks="FilteredTodo"
                     CanMoveLeft="false"
                     CanMoveRight="true"
                     RightColumnStatus="In Progress"
                     OnStatusChange="HandleStatusChange"
                     OnAddTask="args => HandleAddTask(args, &quot;To Do&quot;)" />

        <BoardColumn ColumnName="In Progress"
                     Tasks="FilteredInProgress"
                     CanMoveLeft="true"
                     CanMoveRight="true"
                     LeftColumnStatus="To Do"
                     RightColumnStatus="Done"
                     OnStatusChange="HandleStatusChange"
                     OnAddTask="args => HandleAddTask(args, &quot;In Progress&quot;)" />

        <BoardColumn ColumnName="Done"
                     Tasks="FilteredDone"
                     CanMoveLeft="true"
                     CanMoveRight="false"
                     LeftColumnStatus="In Progress"
                     OnStatusChange="HandleStatusChange"
                     OnAddTask="args => HandleAddTask(args, &quot;Done&quot;)" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private bool loading = true;
    private string? errorMessage;
    private string searchText = "";

    private List<TaskItem> TodoTasks => allTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> InProgressTasks => allTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> DoneTasks => allTasks.Where(t => t.Status == "Done").ToList();
    private int OverdueCount => allTasks.Count(t => t.DueDate < DateTime.Today);

    private List<TaskItem> FilteredTodo => ApplySearch(TodoTasks);
    private List<TaskItem> FilteredInProgress => ApplySearch(InProgressTasks);
    private List<TaskItem> FilteredDone => ApplySearch(DoneTasks);

    private List<TaskItem> ApplySearch(List<TaskItem> tasks) =>
        string.IsNullOrWhiteSpace(searchText)
            ? tasks
            : tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            loading = false;
        }
    }

    private void HandleSearch(string text)
    {
        searchText = text;
    }

    private async Task HandleStatusChange((int TaskId, string NewStatus) change)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(change.TaskId, change.NewStatus);
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to update task: {ex.Message}";
        }
    }

    private async Task HandleAddTask(
        (string Title, string Assignee, string Priority, DateTime DueDate) data,
        string status)
    {
        try
        {
            var task = await TaskService.CreateTaskAsync(data.Title, data.Assignee, data.Priority, data.DueDate);
            if (task.Status != status)
            {
                await TaskService.UpdateTaskStatusAsync(task.Id, status);
            }
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to add task: {ex.Message}";
        }
    }
}

